{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Absolute oral bioavailability of estradiol, the active form released from the query's 17β-ester prodrug, is only 3–5% in fertile women after oral administration, directly demonstrating extensive first-pass loss for the estradiol core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Systemic bioavailability of oral estradiol in young female volunteers was only 11%, still well below the 20% threshold, confirming the low oral availability of the estradiol scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Testosterone undecanoate, a lipophilic steroid 17β-ester prodrug, had absolute oral bioavailability of only 6.8±3.3% in young women, showing that esterification alone does not reliably raise steroid oral bioavailability above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ethinylestradiol has higher absolute oral bioavailability of about 49%, but this is due to the 17α-ethynyl group that blocks first-pass metabolism; the query lacks this protective group and instead has a hydrolyzable 17β-ester, so this high value is not transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "Estramustine phosphate, an estradiol-based prodrug, showed mean oral bioavailability of 43.7% in patients, but its phosphate and nitrogen-mustard substituents alter absorption and metabolism substantially, limiting transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is estradiol 17β-cyclopentylpropionate, an ester prodrug of estradiol. The closest and most transferable evidence—estradiol itself—shows absolute oral bioavailability of only 3–11% in humans, well below 20%. Other steroid ester prodrugs such as testosterone undecanoate also show low oral bioavailability. High-bioavailability analogues rely on structural features absent in the query, such as the 17α-ethynyl group or phosphate/alkylating moieties, and are less transferable. Therefore the prediction is low oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate itself is available in the evidence set.",
    "The potential contribution of lymphatic absorption from the cyclopentylpropionate ester is not directly quantified.",
    "Human oral pharmacokinetic data for estradiol cypionate are scarce, so extrapolation relies on estradiol and related steroid esters."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

